import os, json, time, numpy as np

SHARED_DIR = 'storage/shared/appxE_contribs'
OUT_DIR = 'storage/noesis/nmap'
OUT_MAIN = os.path.join(OUT_DIR, 'research', 'kkt_slack_agreement_v2_1.json')

SNAP_C = 'storage/noesis/latest_centers.txt'
SNAP_R = 'storage/noesis/latest_radii.txt'

def _ensure_dirs():
    os.makedirs(os.path.join(OUT_DIR, 'research'), exist_ok=True)
    os.makedirs(os.path.join(OUT_DIR, 'freezes'), exist_ok=True)

def _ts():
    return time.strftime('%Y-%m-%dT%H:%M:%SZ', time.gmtime())

def _load_snapshot():
    try:
        c = np.loadtxt(SNAP_C, dtype=float).reshape(26,2)
        r = np.loadtxt(SNAP_R, dtype=float).reshape(26,)
        return c, r
    except Exception:
        # conservative fallback: small grid
        centers = []
        rad = 0.08
        for i in range(5):
            for j in range(6):
                if len(centers) < 26:
                    centers.append([0.1 + 0.2*i, 0.1 + 0.15*j])
        return np.array(centers, float), np.full(26, rad, float)

# ---------- Parsing helpers (schema-robust) ----------
def _is_pair(x):
    try:
        return isinstance(x, (list, tuple)) and len(x) == 2 and all(isinstance(v, (int, np.integer)) for v in x)
    except Exception:
        return False

def _norm_pair(p):
    i, j = int(p[0]), int(p[1])
    return (i, j) if i < j else (j, i)

def _read_json_pairs(path):
    # Return (ordered_list_of_pairs, meta_dict)
    try:
        with open(path, 'r') as f:
            data = json.load(f)
    except Exception:
        return [], {}

    # Many shapes; normalize
    # Case A: dict with 'pairs'
    if isinstance(data, dict):
        if 'pairs' in data and isinstance(data['pairs'], list):
            pairs = [ _norm_pair(p) for p in data['pairs'] if _is_pair(p) ]
            K = int(data.get('K', len(pairs)))
            meta = {'K': K, 'method': data.get('method', ''), 'tol': str(data.get('tol', ''))}
            return pairs, meta
        # Case B: dict with 'topk' or 'data' sublist
        for key in ['topk', 'data', 'items', 'list']:
            if key in data and isinstance(data[key], list):
                arr = data[key]
                pairs = []
                for entry in arr:
                    if _is_pair(entry):
                        pairs.append(_norm_pair(entry))
                    elif isinstance(entry, dict):
                        cand = entry.get('pair') or entry.get('pairs')
                        if _is_pair(cand):
                            pairs.append(_norm_pair(cand))
                K = int(data.get('K', len(pairs)))
                meta = {'K': K, 'method': data.get('method', ''), 'tol': str(data.get('tol', ''))}
                return pairs, meta
    # Case C: list-of-pairs
    if isinstance(data, list):
        pairs = [ _norm_pair(p) for p in data if _is_pair(p) ]
        meta = {'K': len(pairs), 'method': '', 'tol': ''}
        return pairs, meta

    return [], {}

def _read_crossings(path):
    try:
        with open(path, 'r') as f:
            data = json.load(f)
    except Exception:
        return []
    xs = []
    if isinstance(data, dict) and isinstance(data.get('crossings'), list):
        for entry in data['crossings']:
            try:
                p1 = entry.get('pair1'); p2 = entry.get('pair2')
                if _is_pair(p1) and _is_pair(p2):
                    xs.append({
                        'pair1': _norm_pair(p1),
                        'pair2': _norm_pair(p2),
                        'native_cross_strict': bool(entry.get('native_cross_strict', False)),
                        'native_cross_inclusive': bool(entry.get('native_cross_inclusive', entry.get('native_cross_strict', False)))
                    })
            except Exception:
                pass
    return xs

def _prefix_from_name(name):
    # Strip known suffixes to form a class key
    s = name
    for tok in [
        '_slack_top_k_1e_8', '_slack_top_k_1e_9',
        '_kkt_top_k_1e_8', '_kkt_top_k_1e_9',
        '_index_map_to_noesis', '_crossings', '.json'
    ]:
        s = s.replace(tok, '')
    if s.endswith('.json'):
        s = s[:-5]
    return s

# Spearman on intersections only (order-sensitive lists)
def _spearman_on_intersection(list_a, list_b):
    # Build ranks from order
    idx_a = {p:i for i,p in enumerate(list_a)}
    idx_b = {p:i for i,p in enumerate(list_b)}
    inter = [p for p in idx_a.keys() if p in idx_b]
    n = len(inter)
    if n < 2:
        return None, n
    ra = np.array([idx_a[p] for p in inter], dtype=float)
    rb = np.array([idx_b[p] for p in inter], dtype=float)
    # Convert to average ranks if ties existed (unlikely here)
    ra_mean = (ra - ra.mean())
    rb_mean = (rb - rb.mean())
    den = np.sqrt((ra_mean**2).sum()) * np.sqrt((rb_mean**2).sum())
    if den == 0:
        return None, n
    rho = float((ra_mean * rb_mean).sum() / den)
    return rho, n

def _jaccard(a, b):
    A, B = set(a), set(b)
    if not A and not B:
        return 1.0
    if not A or not B:
        return 0.0
    return float(len(A & B)) / float(len(A | B))

def _collect_class_entries():
    entries = {}
    try:
        files = sorted(os.listdir(SHARED_DIR))
    except Exception:
        files = []
    for fn in files:
        if not fn.endswith('.json'):
            continue
        path = os.path.join(SHARED_DIR, fn)
        key = _prefix_from_name(fn)
        rec = entries.setdefault(key, {
            'slack': {'1e-9': [], '1e-8': []},
            'kkt':   {'1e-9': [], '1e-8': []},
            'cross': []
        })
        if 'slack_top_k_1e_9' in fn:
            pairs, meta = _read_json_pairs(path)
            rec['slack']['1e-9'].append({'pairs': pairs, 'K': int(meta.get('K', len(pairs)))})
        elif 'slack_top_k_1e_8' in fn:
            pairs, meta = _read_json_pairs(path)
            rec['slack']['1e-8'].append({'pairs': pairs, 'K': int(meta.get('K', len(pairs)))})
        elif 'kkt_top_k_1e_9' in fn:
            pairs, meta = _read_json_pairs(path)
            rec['kkt']['1e-9'].append({'pairs': pairs, 'K': int(meta.get('K', len(pairs)))})
        elif 'kkt_top_k_1e_8' in fn:
            pairs, meta = _read_json_pairs(path)
            rec['kkt']['1e-8'].append({'pairs': pairs, 'K': int(meta.get('K', len(pairs)))})
        elif 'crossings' in fn:
            rec['cross'].extend(_read_crossings(path))
    return entries

def _union_pairs(list_of_sets):
    u = set()
    for s in list_of_sets:
        u |= set(s)
    return u

def _analyze_class(key, rec):
    out = {'key': key, 'tols': {}}
    for tol in ['1e-9', '1e-8']:
        tolres = {'slack_vs_kkt': [], 'k_consistency': None}
        slack_lists = [e['pairs'] for e in rec['slack'][tol] if e['pairs']]
        kkt_lists   = [e['pairs'] for e in rec['kkt'][tol] if e['pairs']]
        # Slack/KKT agreement across available K (pair by pair of lists, truncating to min length)
        for s_list in slack_lists:
            for k_list in kkt_lists:
                m = min(len(s_list), len(k_list))
                if m > 0:
                    s_tr = s_list[:m]
                    k_tr = k_list[:m]
                    jac = _jaccard(s_tr, k_tr)
                    rho, n = _spearman_on_intersection(s_tr, k_tr)
                    tolres['slack_vs_kkt'].append({'K_min': m, 'jaccard': jac, 'spearman': rho, 'n_intersection': n})
        # K-consistency across K for slack (intersection across all slack lists at tol)
        if len(slack_lists) >= 2:
            inter = set(slack_lists[0])
            for lst in slack_lists[1:]:
                inter &= set(lst)
            uni = _union_pairs(slack_lists)
            tolres['k_consistency'] = {
                'n_lists': len(slack_lists),
                'intersection_size': len(inter),
                'union_size': len(uni),
                'intersection_over_union': (len(inter)/len(uni)) if len(uni)>0 else None
            }
        out['tols'][tol] = tolres

    # Eligibility triage via crossings (approx: both pairs appear in any slack list at tol=1e-8)
    eligible_1e8 = set()
    for e in rec['slack']['1e-8']:
        for p in e['pairs']:
            eligible_1e8.add(p)
    n_cross_candidates = 0
    n_cross_native_strict = 0
    for cx in rec['cross']:
        p1 = cx['pair1']; p2 = cx['pair2']
        if p1 in eligible_1e8 and p2 in eligible_1e8:
            n_cross_candidates += 1
            if cx.get('native_cross_strict', False):
                n_cross_native_strict += 1
    out['eligibility'] = {
        'both_near_active_1e8_candidates': n_cross_candidates,
        'native_cross_strict_count': n_cross_native_strict
    }
    return out

def _summarize(all_class_results):
    # Aggregate means for jaccard/spearman where defined
    agg = {'by_tol': {}}
    for tol in ['1e-9', '1e-8']:
        jac_vals, rho_vals = [], []
        for cr in all_class_results:
            blk = cr.get('tols', {}).get(tol, {})
            for svk in blk.get('slack_vs_kkt', []):
                if svk.get('jaccard') is not None:
                    jac_vals.append(float(svk['jaccard']))
                rho = svk.get('spearman')
                if rho is not None:
                    rho_vals.append(float(rho))
        agg['by_tol'][tol] = {
            'mean_jaccard': (sum(jac_vals)/len(jac_vals)) if jac_vals else None,
            'mean_spearman': (sum(rho_vals)/len(rho_vals)) if rho_vals else None,
            'n_pairs_evaluated': len(jac_vals)
        }
    return agg

def _write_outputs(payload):
    _ensure_dirs()
    # Main
    with open(OUT_MAIN, 'w') as f:
        json.dump(payload, f, indent=2)
    # Freeze
    stamp = time.strftime('%Y-%m-%dT%H-%M-%SZ', time.gmtime())
    freeze_path = os.path.join(OUT_DIR, 'freezes', f'kkt_slack_agreement_v2_1_{stamp}.json')
    with open(freeze_path, 'w') as f:
        json.dump(payload, f, indent=2)
    return freeze_path

def construct_packing():
    # Analysis
    entries = _collect_class_entries()
    results = []
    for key, rec in entries.items():
        results.append(_analyze_class(key, rec))
    summary = _summarize(results)
    payload = {
        'generated_at': _ts(),
        'schema': 'v2.1',
        'source_dir': SHARED_DIR,
        'class_count': len(results),
        'summary': summary,
        'results_by_class': results
    }
    try:
        _write_outputs(payload)
    except Exception:
        pass

    # Return baseline packing with tiny shrink
    c0, r0 = _load_snapshot()
    r0 = np.maximum(r0 - 1e-9, 1e-12)
    return c0.astype(float), r0.astype(float)
